#define main original_main
#include "../car-cuda/main.cu"
#undef main
#undef img
#undef offsets_h
#undef offsets_v
#undef kernels
#undef output
#include <fstream>
#include <vector>
#include <string>
#include <algorithm>
constexpr int NI=6840,NK=7866,NO=2622,R=100;
struct Buffer{float *base,*p;int n;Buffer(int count):n(count){cudaMalloc(&base,(n+32)*4);p=base+16;std::vector<float>a(n+32,12345.125f);cudaMemcpy(base,a.data(),a.size()*4,cudaMemcpyHostToDevice);}void put(const float*a){cudaMemcpy(p,a,n*4,cudaMemcpyHostToDevice);}std::vector<float>get(){std::vector<float>a(n);cudaMemcpy(a.data(),p,n*4,cudaMemcpyDeviceToHost);return a;}bool guard(std::vector<float>&v){std::vector<float>a(n+32);cudaMemcpy(a.data(),base,a.size()*4,cudaMemcpyDeviceToHost);bool ok=true;for(int j=0;j<16;j++){v.push_back(a[j]);v.push_back(a[n+16+j]);ok&=a[j]==12345.125f&&a[n+16+j]==12345.125f;}return ok;}~Buffer(){cudaFree(base);}};
int main(){std::vector<float>in(NI+3*NK);std::ifstream f("study_inputs_f32.bin",std::ios::binary);f.read((char*)in.data(),in.size()*4);std::vector<double>expected(NO);std::ifstream e("oracle_f64.bin",std::ios::binary);e.read((char*)expected.data(),NO*8);if(!f||!e)return 2;Buffer image(NI),kernels(NK),oh(NK),ov(NK),output(NO);image.put(in.data());kernels.put(in.data()+NI);oh.put(in.data()+NI+NK);ov.put(in.data()+NI+2*NK);params p={2,3,19,23,9,37,29};auto run=[&](){car<<<11,256>>>(image.p,kernels.p,oh.p,ov.p,output.p,p,1,1,NO);};run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;bool all=true;for(int tr=1;tr<=5;tr++){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int j=0;j<R;j++)run();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/R;auto got=output.get();auto ai=image.get(),ak=kernels.get(),ah=oh.get(),av=ov.get();std::vector<float>a;a.insert(a.end(),ai.begin(),ai.end());a.insert(a.end(),ak.begin(),ak.end());a.insert(a.end(),ah.begin(),ah.end());a.insert(a.end(),av.begin(),av.end());bool ok=status==cudaSuccess&&std::equal(a.begin(),a.end(),in.begin());float par[]={2,3,19,23,9,37,29,1,1,R};a.insert(a.end(),par,par+10);a.insert(a.end(),got.begin(),got.end());double ma=0,mr=0,scaled=0;for(int j=0;j<NO;j++){double err=fabs(double(got[j])-expected[j]);ma=std::max(ma,err);mr=std::max(mr,err/std::max(fabs(expected[j]),1e-300));scaled=std::max(scaled,err/(.00005+.000002*fabs(expected[j])));ok&=std::isfinite(got[j])&&err<=.00005+.000002*fabs(expected[j]);int b=j/(3*19*23),c=(j/(19*23))%3;ok&=got[j]>=b*8+c*2-.00005&&got[j]<=b*8+c*2+6.734375+.00005;}ok&=image.guard(a);ok&=kernels.guard(a);ok&=oh.guard(a);ok&=ov.guard(a);ok&=output.guard(a);all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(tr)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)a.data(),a.size()*4);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"max_scaled_oracle_error\":%.12g,\"convex_hull_check\":true,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",tr,seconds,ok?"true":"false",a.size(),ma,mr,scaled,path.c_str(),a.size());}puts(all?"PASS":"FAIL");return all?0:1;}
